        for clause in cnf:
            for literal in clause:
                var = abs(literal) - 1
                if literal > 0:
                    poly[var][var] += 1
                else:
                    poly[var][var] -= 1
        return poly

    def minimal_order_of_invariants(poly):
        n = len(poly)
        order = 0
        for i in range(n):
            for j in range(i + 1, n):
                if poly[i][j] != 0:
                    order += 1
        return order

